import Animated from "~/components/Animated/Animated";
import { EMAIL } from "~/utils/message";

const PrivacyPolicy = () => {
  return (
    <Animated>
      <h1>Privacy Policy</h1>

      <p>
        Your privacy matters to us. This Privacy Policy explains how Pinktra collects, uses, stores,
        and protects information when you use our website, learning resources, products, and
        development services. By using Pinktra, you agree to this Privacy Policy.
      </p>

      <h2>1. Information We Collect</h2>

      <p>
        Pinktra is designed to minimize data collection. We do not require you to create an account
        or provide personal information to access most of our learning resources.
      </p>

      <p>We may collect limited information such as:</p>

      <ul>
        <li>Browser and device information.</li>
        <li>Anonymous usage statistics.</li>
        <li>Theme, language, and other website preferences stored locally.</li>
        <li>Information you voluntarily provide through email or contact forms.</li>
      </ul>

      <h2>2. Cookies and Local Storage</h2>

      <p>
        Pinktra uses cookies and similar technologies to improve your browsing experience. These may
        be used to remember preferences such as theme, language, and other website settings.
      </p>

      <p>These technologies are not used to identify you personally.</p>

      <h2>3. How We Use Information</h2>

      <p>Any information we receive is used only to:</p>

      <ul>
        <li>Improve the platform and user experience.</li>
        <li>Maintain website functionality.</li>
        <li>Respond to inquiries or support requests.</li>
        <li>Improve learning resources, products, and development services.</li>
      </ul>

      <h2>4. Third-Party Services</h2>

      <p>
        Pinktra may link to third-party websites, tools, repositories, or services. Their privacy
        practices are independent of ours, and we encourage you to review their policies before
        providing any personal information.
      </p>

      <h2>5. Data Security</h2>

      <p>
        We take reasonable measures to protect information and maintain the security of the
        platform. However, no internet transmission or storage system can be guaranteed to be
        completely secure.
      </p>

      <h2>6. Children's Privacy</h2>

      <p>
        Pinktra is not intended to knowingly collect personal information from children. If you
        believe a child has provided personal information, please contact us so appropriate action
        can be taken.
      </p>

      <h2>7. Policy Updates</h2>

      <p>
        This Privacy Policy may be updated periodically to reflect improvements, legal requirements,
        or changes to the platform. Updates become effective once published on this page.
      </p>

      <h2>8. Contact</h2>

      <p>
        If you have any questions about this Privacy Policy or how Pinktra handles information,
        please contact us at <strong>{EMAIL}</strong>.
      </p>
    </Animated>
  );
};

export default PrivacyPolicy;
